/**
 * Application-level access to customers. The UI talks to this service, never to
 * the repository directly.
 */
@Service
public class CustomerService {

    private final CustomerRepository repository;

    public CustomerService(CustomerRepository repository) {
        this.repository = repository;
    }

    /** Returns one page of customers, unfiltered. */
    public List<Customer> list(int offset, int limit, List<CustomerSort> sorts) {
        return repository.findAll(offset, limit, sorts);
    }

    /** Returns one page of the customers that match {@code filter}. */
    public List<Customer> list(int offset, int limit, List<CustomerSort> sorts, CustomerFilter filter) {
        return repository.findAll(offset, limit, sorts, filter);
    }

    /** Returns the total number of customers, unfiltered. */
    public int count() {
        return repository.count();
    }

    /** Returns the number of customers that match {@code filter}. */
    public int count(CustomerFilter filter) {
        return repository.count(filter);
    }
}
