/**
 * Drives the running application in a real, offline Chromium, to check what the
 * browbrowserless tests cannot see: the address bar, and what typing costs the
 * backend.
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class CustomerListBrowserTest extends AbstractBasePlaywrightIT {

    @LocalServerPort
    private int port;

    @Autowired
    private QueryLog queryLog;

    @Override
    public String getUrl() {
        return "http://localhost:" + port + "/";
    }

    @BeforeEach
    void waitForGrid() {
        assertThat(page.getByText("Showing 500 of 500")).isVisible();
        queryLog.clear();
    }

    @Test
    void typingNarrowsTheListWithFewQueriesAndKeepsTheFilterInTheAddressBar() {
        Locator name = page.getByPlaceholder("Filter by name");
        name.pressSequentially("makinen", new Locator.PressSequentiallyOptions().setDelay(40));

        assertThat(page.getByText("Showing 15 of 500")).isVisible();
        assertTrue(page.url().endsWith("/?name=makinen"), "address bar was " + page.url());
        assertTrue(queryLog.countQueries().size() <= 2,
                "Typing ran " + queryLog.countQueries().size() + " count queries");
        assertTrue(queryLog.pageQueries().size() <= 2,
                "Typing ran " + queryLog.pageQueries().size() + " page queries");
    }

    @Test
    void clearingTheFilterRemovesItFromTheAddressBar() {
        Locator name = page.getByPlaceholder("Filter by name");
        name.fill("vir");
        assertThat(page.getByText("Showing 15 of 500")).isVisible();
        name.fill("");

        assertThat(page.getByText("Showing 500 of 500")).isVisible();
        assertEquals(getUrl(), page.url());
    }

    @Test
    void addressBarParametersApplyTheFilterAndFillTheFields() {
        page.navigate(getUrl() + "?name=vir&status=ACTIVE,CLOSED");

        assertThat(page.getByText("Showing 10 of 500")).isVisible();
        assertThat(page.getByPlaceholder("Filter by name")).hasValue("vir");
        MultiSelectComboBoxElement status = MultiSelectComboBoxElement.getByLabel(page, "Status");
        assertEquals(2, status.getSelectedItemCount());
    }
}
