+ * <ul>
+ *   <li>name: the text is split on whitespace into terms, and every term must
+ *       appear in the customer's first name or last name. Case and accents are
+ *       ignored.</li>
+ *   <li>status: with no statuses given, every status matches; otherwise the
+ *       customer's status must be one of them.</li>
+ * </ul>
+ *
+ * @param name     the name text, possibly empty; {@code null} is treated as empty
+ * @param statuses the statuses to show; empty means all of them
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** The filter that matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        statuses = Set.copyOf(statuses);
+    }
+
+    public boolean matches(Customer customer) {
+        return matchesStatus(customer) && matchesName(customer);
+    }
+
+    private boolean matchesStatus(Customer customer) {
+        return statuses.isEmpty() || statuses.contains(customer.status());
+    }
+
+    private boolean matchesName(Customer customer) {
+        String text = fold(name).strip();
+        if (text.isEmpty()) {
+            return true;
+        }
+        String first = fold(customer.firstName());
+        String last = fold(customer.lastName());
+        for (String term : text.split("\\s+")) {
+            if (!first.contains(term) && !last.contains(term)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    /** Lower-cases and strips accents, so that {@code Mäkinen} folds to {@code makinen}. */
+    private static String fold(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return COMBINING_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
