+        Locator name = page.locator("input[placeholder='Filter by name']");
+        name.pressSequentially("makinen", new Locator.PressSequentiallyOptions().setDelay(40));
+
+        assertThat(page.getByText("Showing 15 of 500")).isVisible();
+        assertTrue(page.url().endsWith("/?name=makinen"), "address bar was " + page.url());
+        assertTrue(queryLog.countQueries().size() <= 2,
+                "Typing ran " + queryLog.countQueries().size() + " count queries");
+        assertTrue(queryLog.pageQueries().size() <= 2,
+                "Typing ran " + queryLog.pageQueries().size() + " page queries");
+    }
